"use client";
import { useEffect, useId, useState, type ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./cycling-placeholder.css";

export type CyclingPlaceholderProps = Omit<ComponentProps<"input">, "placeholder"> & {
  /** Examples shown in turn while the field is empty, such as "overdue invoices". */
  examples: string[];
  /** Words before each example, such as "Search for". */
  prefix?: string;
  /** Milliseconds each example stays. */
  interval?: number;
};

/**
 * A text field whose placeholder rolls through examples of what to type, so an empty search box teaches what it can
 * find. The roll pauses while the field has focus and the examples disappear once anything is typed. The field is
 * described by the first example, so assistive technology hears one stable hint. Under reduced motion the examples
 * cross-fade instead of rolling.
 */
export function CyclingPlaceholder({ examples, prefix = "", interval = 2600, className, value, defaultValue, onChange, onFocus, onBlur, ...props }: CyclingPlaceholderProps) {
  const [index, setIndex] = useState(0);
  const [focused, setFocused] = useState(false);
  const [own, setOwn] = useState(String(defaultValue ?? ""));
  const text = value === undefined ? own : String(value);
  const hintId = useId();

  useEffect(() => {
    if (focused || text || examples.length < 2) return;
    const timer = window.setInterval(() => setIndex((current) => (current + 1) % examples.length), interval);
    return () => window.clearInterval(timer);
  }, [focused, text, examples.length, interval]);

  return (
    <span data-slot="cycling-placeholder" className={cn("relative block", className)}>
      <input
        data-slot="cp-input"
        aria-describedby={examples[0] ? hintId : undefined}
        value={text}
        onChange={(event) => {
          if (value === undefined) setOwn(event.target.value);
          onChange?.(event);
        }}
        onFocus={(event) => {
          setFocused(true);
          onFocus?.(event);
        }}
        onBlur={(event) => {
          setFocused(false);
          onBlur?.(event);
        }}
        {...props}
      />
      <span id={hintId} className="sr-only">
        For example, {examples[0]}
      </span>
      {!text && (
        <span data-slot="cp-hint" aria-hidden="true">
          {prefix && <span>{prefix} </span>}
          <span data-slot="cp-window">
            <span key={index} data-slot="cp-example">
              {examples[index]}
            </span>
          </span>
        </span>
      )}
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* cycling-placeholder.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Cycling placeholder: the example rolls up through a one-line window over the empty field. */
  [data-slot="cycling-placeholder"] [data-slot="cp-input"] { width: 100%; height: var(--control-height); padding: 0 12px; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--background); color: var(--foreground); font: inherit; font-size: 14px; outline: none; transition: border-color var(--duration-fast) var(--ease-out); }
  [data-slot="cycling-placeholder"] [data-slot="cp-input"]:focus-visible { border-color: var(--ring); box-shadow: 0 0 0 2px color-mix(in oklab, var(--ring) 30%, transparent); }
  [data-slot="cycling-placeholder"] [data-slot="cp-hint"] { position: absolute; top: 0; left: 13px; right: 12px; display: flex; align-items: center; height: var(--control-height); overflow: hidden; color: var(--muted-foreground); font-size: 14px; white-space: pre; pointer-events: none; }
  [data-slot="cycling-placeholder"] [data-slot="cp-window"] { display: inline-block; min-width: 0; overflow: hidden; height: 1.4em; line-height: 1.4em; text-overflow: ellipsis; }
  [data-slot="cycling-placeholder"] [data-slot="cp-example"] { display: block; overflow: hidden; text-overflow: ellipsis; animation: cp-roll 0.42s var(--ease-out); }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="cycling-placeholder"] [data-slot="cp-example"] { animation: cp-fade 0.3s linear; }
  }
  @keyframes cp-roll { from { opacity: 0; translate: 0 70%; } }
  @media (prefers-reduced-motion: reduce) {
    @keyframes cp-fade { from { opacity: 0; } }
  }
}
